import { expect, test, type Page } from "@playwright/test";
import { existsSync, mkdirSync, readdirSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: 8 s and 1 s vertical clips.
const LONG = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const SHORT = path.resolve("fixtures", "short_1s.mp4");

let launched: LaunchedApp;
let page: Page;

test.beforeAll(async () => {
  test.skip(
    !existsSync(LONG) || !existsSync(SHORT),
    'Run "npm run fixtures" first.',
  );
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
});

test.afterAll(async () => {
  await launched?.app.close();
});

async function shot(name: string) {
  mkdirSync("test-results", { recursive: true });
  await page.screenshot({ path: path.join("test-results", `e2e-${name}.png`) });
}

function filesIn(dir: string): string[] {
  return existsSync(dir) ? readdirSync(dir).sort() : [];
}

test("import b-roll for a product, preview it, delete one, and the files go too", async () => {
  const lib = launched.libraryDir;
  const productsDir = path.join(lib, "products");
  const filmstripsDir = path.join(lib, "cache", "filmstrips");
  let brollDir = "";

  await test.step("pick a library and add a product", async () => {
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill("Levi's 501 Jeans");
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();
  });

  await test.step("clicking the card opens the product page with an empty b-roll section", async () => {
    await page
      .getByRole("listitem")
      .filter({ hasText: "Levi's 501 Jeans" })
      .getByRole("button", { name: /Levi's 501 Jeans/ })
      .first()
      .click();
    await expect(
      page.getByRole("heading", { name: "Levi's 501 Jeans", level: 1 }),
    ).toBeVisible();
    await expect(
      page.getByRole("heading", { name: "No b-roll yet" }),
    ).toBeVisible();
    await shot("broll-empty");
  });

  await test.step("importing two clips fills the grid with thumbnails and duration badges", async () => {
    await page.getByLabel("B-roll files").setInputFiles([LONG, SHORT]);
    const tiles = page
      .getByRole("list", { name: "B-roll clips" })
      .locator("> li");
    await expect(page.getByTestId("broll-duration")).toHaveCount(2, {
      timeout: 60_000,
    });
    await expect(tiles).toHaveCount(2);
    // No placeholder is left over once both clips are in.
    await expect(page.getByTestId("broll-placeholder")).toHaveCount(0);
    for (const img of await tiles.locator("img").all()) {
      await expect(img).toHaveJSProperty("complete", true);
      expect(
        await img.evaluate((el: HTMLImageElement) => el.naturalWidth),
      ).toBe(360);
    }
    for (const badge of await page.getByTestId("broll-duration").all()) {
      await expect(badge).toHaveText(/^\d+\.\ds$/);
    }
    await shot("broll-grid");
  });

  await test.step("both clips are on disk", () => {
    const ids = filesIn(productsDir);
    expect(ids).toHaveLength(1);
    brollDir = path.join(productsDir, ids[0] ?? "", "broll");
    const files = filesIn(brollDir);
    expect(files.filter((f) => f.endsWith(".mp4"))).toHaveLength(2);
    expect(files.filter((f) => f.endsWith(".jpg"))).toHaveLength(2);
    expect(filesIn(filmstripsDir)).toHaveLength(2);
  });

  await test.step("hovering a tile plays a muted preview, leaving removes it", async () => {
    const tile = page
      .getByRole("list", { name: "B-roll clips" })
      .locator("> li")
      .first();
    // The mouse still rests where the card was clicked, which is now over this tile. Move
    // it off first so the browser reports a real enter.
    await page.mouse.move(0, 0);
    await tile.hover();
    await expect(tile.locator("video")).toHaveCount(1);
    await expect(tile.locator("video")).toHaveJSProperty("muted", true);
    await page.mouse.move(0, 0);
    await expect(tile.locator("video")).toHaveCount(0);
  });

  await test.step("clicking a tile opens the larger preview", async () => {
    await page.getByRole("button", { name: "Preview short_1s.mp4" }).click();
    const dialog = page.getByRole("dialog", { name: "short_1s.mp4" });
    await expect(dialog.locator("video")).toBeVisible();
    await dialog.getByRole("button", { name: "Close" }).click();
    await expect(dialog).toBeHidden();
  });

  await test.step("deleting one clip removes its files and keeps the other", async () => {
    const tile = page
      .getByRole("list", { name: "B-roll clips" })
      .locator("> li")
      .filter({
        has: page.getByRole("button", { name: "Preview short_1s.mp4" }),
      });
    await tile.hover();
    await tile.getByRole("button", { name: "Delete short_1s.mp4" }).click();
    const dialog = page.getByRole("dialog", { name: "Delete b-roll" });
    await dialog.getByRole("button", { name: "Delete b-roll" }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByTestId("broll-duration")).toHaveCount(1);

    const files = filesIn(brollDir);
    expect(files.filter((f) => f.endsWith(".mp4"))).toHaveLength(1);
    expect(files.filter((f) => f.endsWith(".jpg"))).toHaveLength(1);
    expect(filesIn(filmstripsDir)).toHaveLength(1);
  });

  await test.step("the products list now says 1 b-roll clip", async () => {
    await page.getByRole("button", { name: /All products/ }).click();
    await expect(
      page.getByRole("listitem").filter({ hasText: "Levi's 501 Jeans" }),
    ).toContainText("1 b-roll clip");
  });

  await test.step("deleting the product removes the remaining b-roll files too", async () => {
    const card = page
      .getByRole("listitem")
      .filter({ hasText: "Levi's 501 Jeans" });
    await card.hover();
    await card.getByRole("button", { name: /^Delete / }).click();
    const dialog = page.getByRole("dialog", { name: "Delete product" });
    await expect(dialog).toContainText("1 b-roll clip");
    await dialog.getByRole("button", { name: "Delete product" }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByText("No products yet")).toBeVisible();
    expect(filesIn(productsDir)).toEqual([]);
    expect(filesIn(filmstripsDir)).toEqual([]);
  });
});
